<?php
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../includes/csrf.php';
require_once __DIR__.'/../../config/database.php';
require_once __DIR__.'/../../includes/functions.php';
if(!in_array($admin['role_name']??'', ['admin','dept_admin','super_admin'], true)){http_response_code(403);exit('403 Forbidden');}
$batchId=(int)($_GET['batch_id']??0); $studentId=(int)($_GET['student_id']??0); $entryId=(int)($_GET['entry_id']??0);
if ($entryId && (!$batchId || !$studentId)) {
    $context=$pdo->prepare('SELECT s.batch_id,f.student_id FROM faculty_marks_entry f JOIN students s ON s.student_id=f.student_id WHERE f.entry_id=:entry_id');
    $context->execute([':entry_id'=>$entryId]);
    if ($found=$context->fetch(PDO::FETCH_ASSOC)) { $batchId=(int)$found['batch_id']; $studentId=(int)$found['student_id']; }
}
function fe($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
try{$batchStmt=$pdo->prepare('SELECT batch_id,batch_name FROM batches WHERE batch_id=:b');$batchStmt->execute([':b'=>$batchId]);$batch=$batchStmt->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Full Marks Edit batch lookup failed: '.$e->getMessage());$batch=null;}
$student=null;$rows=[];$edit=null;$error='';$marksError='';
if(!$batchId||!$studentId||!$batch){$error='A valid batch and student are required.';}else{try{$s=$pdo->prepare('SELECT student_id,student_name,roll_no,designation,qualification,rmc,batch_id FROM students WHERE student_id=:s AND batch_id=:b AND (is_deleted=0 OR is_deleted IS NULL)');$s->execute([':s'=>$studentId,':b'=>$batchId]);$student=$s->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Full Marks Edit student lookup failed: '.$e->getMessage());$error='Unable to load Full Marks Edit data.';}if(!$error&&!$student){$error='Student does not belong to the selected batch.';}if(!$error&&$student){try{$q=$pdo->prepare("SELECT f.entry_id,f.marks_obtained,f.is_absent,p.paper_name,sub.subject_name,at.assessment_type_name,COALESCE(NULLIF(CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN psm.subject_max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN psm.subject_max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN psm.subject_max_final END,0),CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN p.max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN p.max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN p.max_final END,sfm.max_marks) max_marks FROM faculty_marks_entry f JOIN papers p ON p.paper_id=f.paper_id JOIN subjects sub ON sub.subject_id=f.subject_id JOIN assessment_types at ON at.assessment_type_id=f.assessment_type_id JOIN paper_subject_mapping psm ON psm.batch_id=:b AND psm.paper_id=f.paper_id AND psm.subject_id=f.subject_id LEFT JOIN subject_faculty_mapping sfm ON sfm.batch_id=:b2 AND sfm.subject_id=f.subject_id AND sfm.faculty_id=f.faculty_id WHERE f.student_id=:s AND f.paper_id IS NOT NULL ORDER BY p.paper_name,sub.subject_name,at.assessment_type_id,f.entry_id");$q->execute([':b'=>$batchId,':b2'=>$batchId,':s'=>$studentId]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)if((int)$r['entry_id']===$entryId)$edit=$r;}catch(Throwable $e){error_log('Full Marks Edit marks lookup failed: '.$e->getMessage());$marksError='Unable to load Full Marks Edit data.';}}}
$pageTitle='Full Marks Edit';require_once __DIR__.'/../../includes/header.php';
?><div style="display:flex;flex-direction:column;min-height:100vh"><?php require_once __DIR__.'/../../includes/navbar.php';?><div style="display:flex;flex:1"><?php require_once __DIR__.'/../../includes/sidebar.php';?><main style="flex:1;padding:30px;background:#f4f6f8"><h1 style="color:#1f4e79">Full Marks Edit</h1><!-- batch_id=<?=fe($batchId)?> --><!-- student_id=<?=fe($studentId)?> --><!-- student_loaded=<?= $student ? 'yes' : 'no' ?> --><!-- marks_count=<?=count($rows)?> --><?=displayFlash()?><?php if($student):?><div style="background:#fff;padding:20px;border-radius:8px;margin-bottom:20px"><h2>Full Marks Edit</h2><p><b>Student Name:</b> <?=fe($student['student_name'])?> &nbsp; <b>Roll No:</b> <?=fe($student['roll_no'])?></p><p><b>Batch:</b> <?=fe($batch['batch_name'])?> &nbsp; <b>Designation:</b> <?=fe($student['designation'])?> &nbsp; <b>Qualification:</b> <?=fe($student['qualification'])?> &nbsp; <b>RMC:</b> <?=fe($student['rmc'])?></p></div><?php if($edit):?><div style="background:#fff;padding:20px;border-radius:8px;margin-bottom:20px"><h3>Edit Mark</h3><p><?=fe($edit['paper_name'])?> / <?=fe($edit['subject_name'])?> / <?=fe($edit['assessment_type_name'])?></p><p>Current Mark: <?=($edit['is_absent']?'Absent':fe($edit['marks_obtained']))?> | Maximum Mark: <?=fe($edit['max_marks'])?></p><form method="post" action="full_edit_save.php"><?=csrfField()?><input type="hidden" name="entry_id" value="<?=$entryId?>"><input type="hidden" name="batch_id" value="<?=$batchId?>"><input type="hidden" name="student_id" value="<?=$studentId?>"><input type="number" name="new_marks" min="0" max="<?=fe($edit['max_marks'])?>" step="0.01" required><textarea name="reason" required minlength="3" placeholder="Correction Reason"></textarea><button type="submit">Save Changes</button></form></div><?php endif;?><?php if($marksError):?><div class="alert alert-danger"><?=fe($marksError)?></div><?php endif;?><table style="width:100%;background:#fff;border-collapse:collapse"><tr><th>Paper</th><th>Subject</th><th>Assessment Type</th><th>Current Mark</th><th>Maximum Mark</th><th>Action</th></tr><?php if(!$rows):?><tr><td colspan="6">No marks entries are currently available for this student.</td></tr><?php else: foreach($rows as $r):?><tr><td><?=fe($r['paper_name'])?></td><td><?=fe($r['subject_name'])?></td><td><?=fe($r['assessment_type_name'])?></td><td><?=($r['is_absent']?'Absent':fe($r['marks_obtained']))?></td><td><?=fe($r['max_marks'])?></td><td><a href="?batch_id=<?=$batchId?>&student_id=<?=$studentId?>&entry_id=<?=$r['entry_id']?>">Edit</a></td></tr><?php endforeach; endif;?></table><?php elseif($error):?><div class="alert alert-danger"><?=fe($error)?></div><?php else:?><div class="alert alert-danger">Unable to load Full Marks Edit data.</div><?php endif;?></main></div><?php require_once __DIR__.'/../../includes/footer.php';?></div>
